use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap = 0
    let mut first = true
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 { continue }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut nk: Vec<int> = []
            let mut nv: Vec<int> = []
            for i in 0..ks.len() {
                if ks[i] != k {
                    nk.push(ks[i])
                    nv.push(vs[i])
                }
            }
            nk.push(k)
            nv.push(v)
            if (nk.len() as int) > cap {
                println("evict ${nk[0]}")
                let mut mk: Vec<int> = []
                let mut mv: Vec<int> = []
                for i in 1..nk.len() {
                    mk.push(nk[i])
                    mv.push(nv[i])
                }
                nk = mk
                nv = mv
            }
            ks = nk
            vs = nv
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = -1
            let mut nk: Vec<int> = []
            let mut nv: Vec<int> = []
            for i in 0..ks.len() {
                if ks[i] == k {
                    found = vs[i]
                } else {
                    nk.push(ks[i])
                    nv.push(vs[i])
                }
            }
            if found != -1 || ks.len() != nk.len() {
                nk.push(k)
                nv.push(found)
                ks = nk
                vs = nv
            }
            println("${found}")
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let n = ks.len()
                for j in 0..n {
                    let i = n - 1 - j
                    if j > 0 { out = out + " " }
                    out = out + "${ks[i]}"
                }
                println("${out}")
            }
        }
    }
}

